 function pcExecution(page){const t=state.tasks.find(t=>t.id===ctx().params.taskId),valid=t&&pcExpected(t),steps=page.id==='PC-017'?['核对原采购账号与独立档案','核对原订单项、来源SKU、数量、报价和地址','按原确认创建采购单，不执行支付','精确回读外部订单与金额','回传证据，由NAS校验结果']:page.id==='PC-018'?['核对原店铺订单与本批包裹','核对商品行数量、承运商与运单','按原确认回填本批物流','完整回读原店铺履约结果','回传证据，由NAS校验结果']:['核对原店铺、账号与投影版本','校验图片和平台属性','写入当前草稿','同账号唯一完整回读','回传观察证据'];return (t?pcOriginal(page.id):card('原业务任务准入',note('请先从NAS已确认任务进入。尚未绑定原对象、账号与版本，执行已阻断。'),jump('PC-005','查看NAS已确认演示任务')))+card('保留的受控执行步骤',table(['步骤','本次执行记录'],steps.map((name,i)=>[esc(name),valid&&t.executionStep>i?'本地预演已记录':'待原任务核验']),page.id)+note('以下仅预演原任务步骤，不发起真实平台写入或支付。原确认保持不变；回传记录不能自行裁决业务成功。'),button('pc-exec-step','核对并预演下一步骤',true,!valid||t.lock||t.state!=='REQUEST_ACCEPTED'||Date.now()>Date.parse(t.confirmation.expiresAt)||(t.executionStep||0)>=steps.length));}
