  if(key.startsWith('config.')){state.config[key.split('.')[1]]=v;if(['config.nasUrl','config.device'].includes(key)){state.config.connection='配置已变化，尚未重新核对';state.config.running=false;}if(repaint&&key==='config.case')render();return;}
  if(key.startsWith('login.')){state.login[key.split('.')[1]]=v;state.login.verified=false;state.login.status='配置已变化，待本人登录与核验';if(repaint)render();return;}
  const o=active(currentKind(),key==='reconcileCase');if(!o)return;if(['SUBMIT_REQUESTED','PUBLISH_REQUESTED'].includes(o.publication)&&key!=='reconcileCase'&&key!=='readCase')return block({state:'原外部写请求尚未证实，内容与条件保持只读'});
  if(key.startsWith('product.')){const part=key.split('.')[1];if(['JD-002','PRD-005'].includes(ctx().params.__currentId)){o.attrEdit=o.attrEdit||{};o.attrEdit[part]=v;}else{o.edit=o.edit||{...productSnapshot(o),color:o.color,size:o.size};o.edit[part]=v;}}
